      "metaDescription": "生成活动二维码，让宾客一扫就把日期、时间和地点存入日历。适用于请柬、海报和门票，完全免费。",
      "intro": "活动二维码让人们只需扫一扫，就能把你的活动加入日历——日期、时间、地点和说明一应俱全。放在请柬、海报、门票和邮件签名里都很合适。",
